using namespace nvcuda;
#define CUDA_CHECK(x) do { cudaError_t e=(x); if(e!=cudaSuccess){std::ostringstream s; s<<"CUDA error "<<cudaGetErrorString(e); throw std::runtime_error(s.str());} } while(0)
struct Shape { int m,k,n; };
constexpr float ATOL=1e-3f, RTOL=1e-4f;
std::string ts(){std::time_t t=std::time(nullptr);std::tm tm{};gmtime_r(&t,&tm);std::ostringstream s;s<<std::put_time(&tm,"%Y-%m-%dT%H:%M:%SZ");return s.str();}
std::vector<float> input(std::size_t n,unsigned seed){std::mt19937 g(seed);std::uniform_real_distribution<float>d(-1,1);std::vector<float>v(n);for(float&x:v)x=d(g);return v;}
void cpu(const std::vector<float>&a,const std::vector<float>&b,std::vector<float>&c,Shape s){std::fill(c.begin(),c.end(),0);for(int r=0;r<s.m;r++)for(int k=0;k<s.k;k++){float av=a[r*s.k+k];for(int col=0;col<s.n;col++)c[r*s.n+col]+=av*b[k*s.n+col];}}
__global__ void v1(const float*a,const float*b,float*c,int M,int K,int N){int r=blockIdx.y*blockDim.y+threadIdx.y,col=blockIdx.x*blockDim.x+threadIdx.x;if(r>=M||col>=N)return;float x=0;for(int k=0;k<K;k++)x+=a[r*K+k]*b[k*N+col];c[r*N+col]=x;}
template<int T> __global__ void tiled(const float*a,const float*b,float*c,int M,int K,int N){__shared__ float As[T][T],Bs[T][T];int tx=threadIdx.x,ty=threadIdx.y,r=blockIdx.y*T+ty,col=blockIdx.x*T+tx;float acc=0;for(int kt=0;kt<K;kt+=T){int ar=r,ak=kt+tx,bk=kt+ty,bc=col;As[ty][tx]=(ar<M&&ak<K)?a[ar*K+ak]:0;Bs[ty][tx]=(bk<K&&bc<N)?b[bk*N+bc]:0;__syncthreads();for(int j=0;j<T&&kt+j<K;j++)acc+=As[ty][j]*Bs[j][tx];__syncthreads();}if(r<M&&col<N)c[r*N+col]=acc;}
__global__ void wmmaKernel(const half*a,const half*b,float*c,int M,int K,int N){int tileM=blockIdx.y,tileN=blockIdx.x;wmma::fragment<wmma::accumulator,16,16,16,float> acc;wmma::fill_fragment(acc,0.0f);for(int kt=0;kt<K;kt+=16){wmma::fragment<wmma::matrix_a,16,16,16,half,wmma::row_major> af;wmma::fragment<wmma::matrix_b,16,16,16,half,wmma::col_major> bf;const half*ap=a+(tileM*16)*K+kt;const half*bp=b+(tileN*16)*K+kt;wmma::load_matrix_sync(af,ap,K);wmma::load_matrix_sync(bf,bp,K);wmma::mma_sync(acc,af,bf,acc);}float*cp=c+(tileM*16)*N+tileN*16;wmma::store_matrix_sync(cp,acc,N,wmma::mem_row_major);}
void launch(const std::string&ver,const float*a,const float*b,float*c,Shape s){if(ver=="V1"){dim3 bl(16,16),gr((s.n+15)/16,(s.m+15)/16);v1<<<gr,bl>>>(a,b,c,s.m,s.k,s.n);}else{int t=std::stoi(ver.substr(4));dim3 bl(t,t),gr((s.n+t-1)/t,(s.m+t-1)/t);if(t==8)tiled<8><<<gr,bl>>>(a,b,c,s.m,s.k,s.n);else if(t==16)tiled<16><<<gr,bl>>>(a,b,c,s.m,s.k,s.n);else tiled<32><<<gr,bl>>>(a,b,c,s.m,s.k,s.n);}CUDA_CHECK(cudaPeekAtLastError());}
struct Guard{float*raw=nullptr,*p=nullptr;std::size_t n=0;static constexpr int G=16;void alloc(std::size_t z){n=z;CUDA_CHECK(cudaMalloc((void**)&raw,(z+2*G)*sizeof(float)));p=raw+G;std::vector<std::uint32_t>h(z+2*G,0x7fc12345);CUDA_CHECK(cudaMemcpy(raw,h.data(),h.size()*4,cudaMemcpyHostToDevice));}bool ok()const{std::uint32_t h[2*G];CUDA_CHECK(cudaMemcpy(h,raw,G*4,cudaMemcpyDeviceToHost));CUDA_CHECK(cudaMemcpy(h+G,raw+G+n,G*4,cudaMemcpyDeviceToHost));for(auto x:h)if(x!=0x7fc12345)return false;return true;}~Guard(){if(raw)cudaFree(raw);}};
struct Err{double abs=0,rel=0,rmse=0,scale=0;bool guard=false,pass=false;};
Err compare(const std::vector<float>&r,const std::vector<float>&g,bool guard){Err e;e.guard=guard;double q=0;for(std::size_t i=0;i<r.size();i++){double d=std::abs((double)r[i]-g[i]);e.abs=std::max(e.abs,d);e.scale=std::max(e.scale,std::abs((double)r[i]));e.rel=std::max(e.rel,d/std::max(std::abs((double)r[i]),1e-12));q+=d*d;}e.rmse=std::sqrt(q/r.size());e.pass=e.guard&&e.abs<=ATOL+RTOL*e.scale;return e;}
void makeBcol(const std::vector<float>&b,std::vector<half>&bc,Shape s){bc.resize((std::size_t)s.n*s.k);for(int k=0;k<s.k;k++)for(int n=0;n<s.n;n++)bc[(std::size_t)n*s.k+k]=__float2half(b[(std::size_t)k*s.n+n]);}
void makeHalf(const std::vector<float>&x,std::vector<half>&h){h.resize(x.size());for(std::size_t i=0;i<x.size();i++)h[i]=__float2half(x[i]);}
Err runCase(const std::string&ver,Shape s,std::ostream&out){auto a=input((std::size_t)s.m*s.k,100+s.m),b=input((std::size_t)s.k*s.n,200+s.n);std::vector<float>ref,got((std::size_t)s.m*s.n);std::vector<half>ha,hb;bool wm=ver=="V3-WMMA-FP16";if(wm){makeHalf(a,ha);makeBcol(b,hb,s);ref.resize(got.size());std::vector<float>aq(a.size()),bq(b.size());for(std::size_t i=0;i<a.size();i++)aq[i]=__half2float(ha[i]);for(int k=0;k<s.k;k++)for(int n=0;n<s.n;n++)bq[(std::size_t)k*s.n+n]=__half2float(hb[(std::size_t)n*s.k+k]);cpu(aq,bq,ref,s);}else{ref.resize(got.size());cpu(a,b,ref,s);}float*da=nullptr,*db=nullptr;Guard dc;Err e;try{if(wm){CUDA_CHECK(cudaMalloc((void**)&da,ha.size()*sizeof(half)));CUDA_CHECK(cudaMalloc((void**)&db,hb.size()*sizeof(half)));dc.alloc(got.size());CUDA_CHECK(cudaMemcpy(da,ha.data(),ha.size()*sizeof(half),cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(db,hb.data(),hb.size()*sizeof(half),cudaMemcpyHostToDevice));wmmaKernel<<<dim3((s.n+15)/16,(s.m+15)/16),32>>>((half*)da,(half*)db,dc.p,s.m,s.k,s.n);}else{CUDA_CHECK(cudaMalloc((void**)&da,a.size()*4));CUDA_CHECK(cudaMalloc((void**)&db,b.size()*4));dc.alloc(got.size());CUDA_CHECK(cudaMemcpy(da,a.data(),a.size()*4,cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice));launch(ver,da,db,dc.p,s);}CUDA_CHECK(cudaDeviceSynchronize());CUDA_CHECK(cudaMemcpy(got.data(),dc.p,got.size()*4,cudaMemcpyDeviceToHost));e=compare(ref,got,dc.ok());}catch(const std::exception&x){out<<ts()<<','<<ver<<','<<s.m<<','<<s.k<<','<<s.n<<",ERROR,ERROR,ERROR,ERROR,FAIL,FAIL,\""<<x.what()<<"\"\n";if(da)cudaFree(da);if(db)cudaFree(db);throw;}out<<ts()<<','<<ver<<','<<s.m<<','<<s.k<<','<<s.n<<','<<std::setprecision(10)<<e.abs<<','<<e.rel<<','<<e.rmse<<','<<(ATOL+RTOL*e.scale)<<','<<(e.guard?"PASS":"FAIL")<<','<<(e.pass?"PASS":"FAIL")<<",\"\"\n";if(da)cudaFree(da);if(db)cudaFree(db);return e;}
double timed(const std::string&v,Shape s,int reps){auto a=input((std::size_t)s.m*s.k,7),b=input((std::size_t)s.k*s.n,8);float *da=nullptr,*db=nullptr,*dc=nullptr;CUDA_CHECK(cudaMalloc((void**)&da,a.size()*4));CUDA_CHECK(cudaMalloc((void**)&db,b.size()*4));CUDA_CHECK(cudaMalloc((void**)&dc,(std::size_t)s.m*s.n*4));CUDA_CHECK(cudaMemcpy(da,a.data(),a.size()*4,cudaMemcpyHostToDevice));CUDA_CHECK(cudaMemcpy(db,b.data(),b.size()*4,cudaMemcpyHostToDevice));for(int i=0;i<20;i++)launch(v,da,db,dc,s);CUDA_CHECK(cudaDeviceSynchronize());cudaEvent_t st,sp;CUDA_CHECK(cudaEventCreate(&st));CUDA_CHECK(cudaEventCreate(&sp));CUDA_CHECK(cudaEventRecord(st));for(int i=0;i<reps;i++)launch(v,da,db,dc,s);CUDA_CHECK(cudaEventRecord(sp));CUDA_CHECK(cudaEventSynchronize(sp));float ms;CUDA_CHECK(cudaEventElapsedTime(&ms,st,sp));cudaEventDestroy(st);cudaEventDestroy(sp);cudaFree(da);cudaFree(db);cudaFree(dc);return ms/reps;}
void info(){cudaDeviceProp p{};CUDA_CHECK(cudaGetDeviceProperties(&p,0));std::cout<<"gpu_name="<<p.name<<"\ncompute_capability="<<p.major<<'.'<<p.minor<<"\ncuda_runtime_version=12060\nsm_count="<<p.multiProcessorCount<<"\nwarp_size="<<p.warpSize<<"\n";}
int main(int ac,char**av){try{std::string mode,ver="V1",raw;Shape s{};int reps=1000;for(int i=1;i<ac;i++){std::string a=av[i];auto val=[&](){return std::string(av[++i]);};if(a=="--device-info")mode="info";else if(a=="--correctness")mode="correct";else if(a=="--benchmark-single")mode="bench";else if(a=="--version")ver=val();else if(a=="--raw")raw=val();else if(a=="--m")s.m=std::stoi(val());else if(a=="--k")s.k=std::stoi(val());else if(a=="--n")s.n=std::stoi(val());else if(a=="--repetitions")reps=std::stoi(val());}if(mode=="info"){info();return 0;}if(mode=="correct"){std::ofstream o(raw);o<<"timestamp,version,M,K,N,max_abs_error,max_rel_error,rmse,tolerance,guard_status,correctness,error_message\n";Shape cs[]={{1,1,1},{2,3,4},{15,16,17},{16,17,15},{17,15,16},{31,32,33},{32,33,31},{33,31,32},{128,256,64},{257,129,513},{63,65,97},{511,513,127},{512,512,512}};std::string vs[]={"V1","V2-T8","V2-T16","V2-T32"};int total=0,pass=0;for(auto v:vs)for(auto q:cs){auto e=runCase(v,q,o);total++;pass+=e.pass;}std::cout<<"cases="<<total<<" pass="<<pass<<"\n";return pass==total?0:2;}if(mode=="bench"){if(!s.m||!s.k||!s.n)throw std::invalid_argument("shape required");std::cout<<std::setprecision(12)<<timed(ver,s,reps)<<"\n";return 0;}throw std::invalid_argument("mode required");}catch(const std::exception&e){std::cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
